__NUXT_JSONP__("/inclusion/publicaciones", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{posts:[{slug:"cuando_el_desastre_golpea_distinto_mujeres_y_hombres_tras_el_huracan_otis",title:"Cuando el desastre golpea distinto: mujeres y hombres tras el huracán Otis",date:"2026-05-04T06:00:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F7aea98e9-3923-4f9f-8d26-f18231e79b35\u002F",autor:"Ethos, Centro Nacional de Prevención de Desastres ",category:a,extracto:"El huracán Otis evidenció cómo las desigualdades influyen en la preparación, los impactos y la recuperación tras un desastre.  Este informe analiza, desde una perspectiva de género e interseccionalidad, cómo mujeres, población indígena y afromexicana enfrentaron de forma diferenciada los efectos del huracán en Acapulco, y propone recomendaciones para construir respuestas más justas y efectivas.",file:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F12bb5aff-9368-40ac-b7c6-1d2866421317\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fcuando_el_desastre_golpea_distinto_mujeres_y_hombres_tras_el_huracan_otis",extension:c,createdAt:f,updatedAt:f},{slug:"conectadas_al_cambio_por_un_trabajo_justo_para_las_mujeres_en_plataformas_digitales",title:"Conectadas al cambio: por un trabajo justo para las mujeres en plataformas digitales",date:"2026-01-29T21:30:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fb777d5d7-cd1f-4afd-b80b-6eb9e1011bc3\u002F","img-alt":"Por un trabajo justo para las mujeres en plataformas digitales",autor:g,category:a,extracto:"El objetivo de este documento es analizar y evidenciar las barreras sistémicas que excluyen a las mujeres de este sector, con base en la experiencia directa de las trabajadoras. A través de la sistematización de entrevistas y talleres con colectivas de conductoras y repartidoras, se contrastan las propuestas de la reforma en materia de trabajo en plataformas digitales con la realidad cotidiana. El análisis muestra cómo la violencia de género, la opacidad de los algoritmos y la falta de una red de cuidados convierten la supuesta “flexibilidad laboral” en una fuente de precariedad para ellas. A partir de este diagnóstico, se presentan recomendaciones de política pública y buenas prácticas empresariales dirigidas a cerrar la brecha entre la ley y la realidad, para que la promesa del trabajo justo en la era digital sea, verdaderamente, para todas y todos. ",file:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F651cff88-f77e-4a4c-a59c-f8b0d6873e38\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fconectadas_al_cambio_por_un_trabajo_justo_para_las_mujeres_en_plataformas_digitales",extension:c,createdAt:"2026-07-19T00:56:17.268Z",updatedAt:"2026-07-19T00:56:17.269Z"},{slug:"evidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico",title:"Evidence to Integrate Gender Perspective in Disaster Risk Management in Mexico",date:"2025-10-14T17:25:28.004Z",img:"https:\u002F\u002Fucarecdn.com\u002F21a776b0-1697-4335-98bb-c95ebc391e83\u002F","img-alt":"Disaster Risk Management in Mexico",autor:h,category:a,extracto:"We want to generate quantitative evidence to measure and understand the differentiated impacts of disasters on women, including those related to gender-based violence, highlight the need to include this information in the National Disaster Risk Management strategies and share it with key stakeholders and * Promote evidence-based decision-making with a gender perspective in the development of DRM strategies.",file:"https:\u002F\u002Fucarecdn.com\u002Fe1ff98bf-bf12-48af-8385-f6abec559c7b\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fevidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico",extension:c,createdAt:e,updatedAt:"2025-11-25T01:24:03.289Z"},{slug:"evidence_for_integrating_the_gender_perspective_into_comprehensive_disaster_risk_management_in_mexico",title:"Evidence for Integrating the Gender Perspective into Comprehensive Disaster Risk Management in Mexico",date:"2025-10-14T17:05:58.063Z",img:"https:\u002F\u002Fucarecdn.com\u002F9a378ae9-4b9c-448a-9ed4-0878a22bb795\u002F","img-alt":"Disaster risk management",autor:h,category:a,extracto:"Disasters in Mexico are not only environmental but also deeply social. Their impacts are magnified by structural inequalities – poverty, gender-based violence, and unequal access to resources. Women, in particular, face disproportionate risks: 70.1% of Mexican women aged 15 and older have experienced violence, and their labor force participation rate (46%) remains far below that of men (76.3%). These structural inequalities heighten vulnerability before, during, and after disasters, exacerbating physical, social, and economic insecurity.",file:"https:\u002F\u002Fucarecdn.com\u002F4ac134d0-a697-4f3c-9dbd-e1c6b0107f36\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fevidence_for_integrating_the_gender_perspective_into_comprehensive_disaster_risk_management_in_mexico",extension:c,createdAt:e,updatedAt:e},{slug:"sembrando_el_cambio-_hacia_un_futuro_con_trabajo_justo_para_las_trabajadoras_agricolas_en_mexico",title:"Sembrando el cambio. Hacia un futuro con trabajo justo para las trabajadoras agrícolas en México",date:"2025-09-26T19:36:48.183Z",img:"https:\u002F\u002Fucarecdn.com\u002F20a9d43c-6811-4ea1-bc91-ecce211366da\u002F","img-alt":"Sembrando el cambio",autor:"Ethos, Fundación Avina, Oxfam México, ProDESC",category:a,extracto:"Este documento analiza algunas de las principales barreras estructurales que enfrentan las trabajadoras agrícolas en México para acceder a un trabajo justo, con el objetivo de visibilizar su situación y generar recomendaciones de políticas públicas que contribuyan a garantizar sus derechos laborales y mejorar su calidad de vida.",file:"https:\u002F\u002Fucarecdn.com\u002F3a367950-03ba-49ff-b2df-8944a4aea4fb\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fsembrando_el_cambio-_hacia_un_futuro_con_trabajo_justo_para_las_trabajadoras_agricolas_en_mexico",extension:c,createdAt:i,updatedAt:i},{slug:"manifiesto_unidas_por_el_trabajo_justo_y_la_dignidad_laboral_de_las_mujeres",title:"Manifiesto UNIDAS: Por el trabajo justo y la dignidad laboral de las mujeres",date:"2025-03-25T22:22:20.616Z",img:"https:\u002F\u002Fucarecdn.com\u002F87db4246-801e-4855-8c38-3bad4d313636\u002F","img-alt":"UNIDAS Red de mujeres por el trabajo justo",autor:g,category:a,extracto:"En México, más de la mitad de la población trabaja en la economía informal. Esto implica una situación de desprotección social y falta de acceso a derechos, especialmente para las mujeres que se encuentran en mayor vulnerabilidad. Por eso lanzamos UNIDAS: Red de mujeres por el trabajo justo, un esfuerzo colectivo que nace de la necesidad urgente de transformar la realidad laboral de miles de mujeres en nuestro país. ",file:"https:\u002F\u002Fucarecdn.com\u002F7dbc97bc-5d23-4c46-8914-e7d0f24641c7\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fmanifiesto_unidas_por_el_trabajo_justo_y_la_dignidad_laboral_de_las_mujeres",extension:c,createdAt:d,updatedAt:d},{slug:"cuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",title:"Cuidados para la primera infancia: Recomendaciones hacia la conformación del Sistema Nacional de Cuidados",date:"2025-03-18T14:41:00.000Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffca2a0ef-b4dd-4e5f-9a7f-c17d24f27d70\u002F-\u002Fcrop\u002F1047x1377\u002F18,15\u002F-\u002Fpreview\u002F","img-alt":"Cuidados para la primera infancia",autor:"Ethos, Early Institute y el Centro de Investigación Económica y Presupuestaria ",category:a,extracto:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez. ",file:"https:\u002F\u002Fucarecdn.com\u002Fb2c423fb-64a1-42e7-9f85-07fff85a84e8\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fcuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",extension:c,createdAt:j,updatedAt:j},{slug:"organizaciones_de_la_sociedad_civil_celebran_la_aprobacion_de_la_reforma_para_personas_trabajadoras_en_plataformas_digitales-_posicionamiento_colectivo",title:"Organizaciones de la sociedad civil celebran la aprobación de la reforma para personas trabajadoras en plataformas digitales. Posicionamiento colectivo",date:"2024-12-13T20:52:32.911Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd84c7881-5594-4bb7-80a1-657be180e92e\u002F",autor:"Ethos, Fundación Avina, Oxfam México y ProDESC",category:a,extracto:"Las organizaciones firmantes celebramos la aprobación por el Congreso de la Unión de la reforma a la Ley Federal del Trabajo en materia de plataformas digitales, que busca garantizar los derechos laborales de las personas trabajadoras de este sector. Esta reforma representa un avance significativo en la protección de los derechos de miles de personas trabajadoras, quienes hasta ahora han operado en un marco de incertidumbre y precariedad laboral.",file:"https:\u002F\u002Fucarecdn.com\u002F3c67d51e-5302-4e85-a54d-0c3c89a613d6\u002F",tags:[{tag:"inclusión"},{tag:"plataformas digitales"},{tag:"posicionamiento colectivo"},{tag:"reforma laboral"},{tag:"trabajo digno"}],toc:[],dir:b,path:"\u002Fpublicaciones\u002Forganizaciones_de_la_sociedad_civil_celebran_la_aprobacion_de_la_reforma_para_personas_trabajadoras_en_plataformas_digitales-_posicionamiento_colectivo",extension:c,createdAt:d,updatedAt:d}],micrositios:[],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("inclusion","\u002Fpublicaciones",".md","2025-04-23T06:21:15.399Z","2025-11-25T01:24:03.288Z","2026-07-19T00:56:17.270Z","Ethos, Fundación Avina, ProDESC y Oxfam México","Ethos","2025-11-25T01:24:03.300Z","2025-04-23T06:21:15.398Z")));